      hu: ["A beruházás értéke eléri az 5,5 milliárd dollárt", "A kereskedelmi termelés 2022-ben indult el", "Éves szinten 300 000 tonna réztermelés várható", "3500 méteres magasságban fekszik Moqueguában", "28 darab teljesen önvezető teherautót használnak", "A bánya várható élettartama legalább 30 év"],
