      hu: ["A Pan American Silver üzemelteti", "Kereskedelmi aranybányászat 2011 óta", "Oxidércekből történő aranykinyerés", "La Arena II projekt a jövőbeli réztermelésért", "Huamachuco tartományban található", "Halomlúgozási technológia alkalmazása"],
