    name: { de: "Marcona-Mine", hu: "Marcona bánya", ro: "Mina Marcona", en: "Marcona Mine"},
    image: "/poi-images/ind-marcona-economic-v2.webp",
    description: {
      de: "Die einzige große Eisenerzmine in Peru, die sich nahe der Küste in der Region Ica befindet.",
      hu: "Az egyetlen nagy vasércbánya Peruban, amely a tengerpart közelében, az Ica régióban található.",
      ro: "Singura mare mină de minereu de fier din Peru, situată lângă coastă, în regiunea Ica.",
      en: "The only major iron ore mine in Peru, located near the coast in the Ica region.",
      es: "La única gran mina de mineral de hierro en Perú, situada cerca de la costa en la región de Ica.",
      pt: "A única grande mina de minério de ferro no Peru, localizada perto da costa na região de Ica.",
      fr: "La seule grande mine de minerai de fer au Pérou, située près de la côte dans la région d'Ica.",
    },
    descriptionAdvanced: {
      de: "Die Marcona-Mine in der Region Ica ist Perus einziger bedeutender Eisenerzproduzent. Sie befindet sich im Distrikt Marcona und wird von Shougang Hierro Perú, einer Tochtergesellschaft der chinesischen Shougang-Gruppe, betrieben. Die Mine hat eine lange Geschichte, die bis in die 1950er Jahre zurückreicht, und wurde 1992 privatisiert. Die Erze werden im Tagebau gewonnen und über ein Förderbandsystem zum Hafen von San Nicolás transportiert, wo sie für den Export nach China und in andere Weltmärkte aufbereitet werden. In den letzten Jahren wurden massive Investitionen in die Modernisierung der Anlagen und die Erweiterung der Produktionskapazität getätigt, um die steigende Nachfrage nach Stahlrohstoffen zu decken. Marcona ist nicht nur industriell wichtig, sondern auch eine wichtige Quelle für Steuereinnahmen und Arbeitsplätze an der zentralperuanischen Küste.",
      hu: "A Marcona bánya Ica régióban Peru egyetlen jelentős vasérc-termelője. A bánya Marcona kerületben található, és a kínai Shougang Group leányvállalata, a Shougang Hierro Perú üzemelteti. A bánya hosszú múltra tekint vissza, amely az 1950-es évekig nyúlik vissza, és 1992-ben került sor a privatizációjára. Az ércet külszíni fejtéssel termelik ki, majd egy szállítószalag-rendszeren keresztül juttatják el San Nicolás kikötőjébe, ahol az exportra történő feldolgozás zajlik, elsősorban a kínai és más világpiacok számára. Az elmúlt években jelentős beruházások történtek a létesítmények modernizálására és a termelési kapacitás bővítésére, hogy kielégítsék az acélipari alapanyagok iránti növekvő keresletet. Marcona nemcsak ipari szempontból kiemelkedő, hanem a közép-perui tengerpart fontos adóbevételi és munkahelyi forrása is.",
      ro: "Mina Marcona din regiunea Ica este singurul producător major de minereu de fier din Peru. Situată în districtul Marcona, aceasta este operată de Shougang Hierro Perú, o filială a grupului chinez Shougang. Mina are o istorie îndelungată, care datează din anii 1950, fiind privatizată în anul 1992. Minereurile sunt extrase în cariere de suprafață și transportate printr-un sistem de benzi transportoare către portul San Nicolás, unde sunt procesate pentru export către China și alte piețe globale. În ultimii ani, s-au realizat investiții masive în modernizarea instalațiilor și extinderea capacității de producție pentru a satisface cererea crescută de materii prime pentru oțel. Marcona nu este doar un centru industrial esențial, ci și o sursă vitală de venituri fiscale și locuri de muncă pentru coasta centrală a statului Peru.",
      en: "The Marcona Mine, located in the Ica region, is Peru's only significant iron ore producer. Situated in the Marcona district, it is operated by Shougang Hierro Perú, a subsidiary of the Chinese Shougang Group. The mine has a long history dating back to the 1950s and was privatized in 1992. Ores are extracted through open-pit mining and transported via a conveyor belt system to the port of San Nicolás, where they are processed for export to China and other world markets. In recent years, massive investments have been made to modernize the facilities and expand production capacity to meet the rising demand for steel raw materials. Marcona is not only industrially prominent but also serves as a vital source of tax revenue and employment along the central Peruvian coast.",
      es: "La mina Marcona es un elemento notable de la geografía y cultura peruana. Es la única gran mina de mineral de hierro en Perú, situada cerca de la costa en la región de Ica. Única gran explotación de hierro. Cerca de la costa pacífica. Este sitio desempeña un papel en la economía peruana, desde la minería hasta la agricultura y la pesca. Como muchos lugares significativos en el Perú, este sitio une las particularidades regionales entre el Pacífico, los Andes y la Amazonía con una importancia global. Contribuye al perfil diverso de Perú, desde el legado inca y Machu Picchu hasta Lima y la cuenca del Amazonas.",
      pt: "A mina Marcona é um elemento notável da geografia e cultura peruana. É a única grande mina de minério de ferro no Peru, localizada perto da costa na região de Ica. Única grande mina de ferro. Perto da costa. Este local desempenha um papel na economia peruana, desde a mineração de cobre até à agricultura de quinoa e à pesca no Pacífico. Como muitos locais importantes no Peru, este sítio une características regionais entre o Pacífico, os Andes e a Amazónia com uma importância abrangente. Assim, este local contribui para o perfil multifacetado do Peru, desde a herança Inca e Machu Picchu até Lima e a bacia amazónica.",
      fr: "La mine de Marcona est un élément remarquable de la géographie et de la culture péruviennes. C'est la seule grande mine de minerai de fer au Pérou, située près de la côte dans la région d'Ica. Seule grande mine de fer. Proche de la côte. Ce site joue un rôle dans l'économie péruvienne, de l'extraction du cuivre à l'agriculture du quinoa et à la pêche dans le Pacifique. Comme beaucoup de sites importants au Pérou, ce lieu réunit des particularités régionales entre le Pacifique, les Andes et l'Amazonie avec une importance globale. Il contribue ainsi au profil diversifié du Pérou, de l'héritage inca et du Machu Picchu à Lima et au bassin amazonien.",
    },
