      hu: ["Peru egyetlen vasércbányája", "A Shougang Hierro Perú üzemelteti", "A privatizáció 1992-ben történt", "Szállítószalaggal viszik San Nicolás kikötőjébe", "Fő vásárlója a kínai acélipar", "Ica régió tengerpartján található"],
