      hu: ["A bánya megnyitása 2010-ben történt", "A Sechura-sivatagban (Piura) található", "Amerika egyik legnagyobb foszfáttermelője", "Mosaic, Mitsui és Franco-Nevada konzorcium", "A műtrágyaipar fontos alapanyaga", "Közvetlen hozzáférés Bayóvar kikötőjéhez"],
      ro: ["Inaugurarea minei în anul 2010", "Situată în deșertul Sechura (Piura)", "Unul dintre marii producători de fosfați din America", "Consorțiu format din Mosaic, Mitsui și Franco-Nevada", "Materie primă vitală pentru îngrășăminte", "Acces direct la portul maritim Bayóvar"],
      en: ["Inauguration of the mine in 2010", "Located in the Sechura Desert (Piura)", "One of the largest phosphate producers in the Americas", "Consortium of Mosaic, Mitsui, and Franco-Nevada", "Essential raw material for the fertilizer industry", "Direct access to the Bayóvar shipping port"],
      es: ["Uno de los yacimientos de fosfato más grandes de Sudamérica, crucial para la producción de fertilizantes.", "Ubicado en el territorio de la República del Perú.", "Situado entre la cordillera de los Andes, el desierto costero y la cuenca del Amazonas.", "Desempeña un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["Uma das maiores jazidas de fosfato da América do Sul, crucial para a produção de fertilizantes.", "Localizado no território da República do Peru.", "Inserido entre a cordilheira dos Andes, o deserto costeiro e a Bacia Amazônica.", "Desempenha um papel na identidade local da região.", "Conhecido por sua importância paisagística ou cultural."],
      fr: ["L'un des plus grands gisements de phosphate d'Amérique du Sud, crucial pour la production d'engrais.", "Situé sur le territoire de la République du Pérou.", "Nichée entre la cordillère des Andes, le désert côtier et le bassin amazonien.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
