      hu: ["A projekt 2004-ben kezdte meg működését", "Az Urubamba-medencében (Cusco) található", "A készleteket a Shell fedezte fel (1982-1983)", "Csővezetékeken szállítják az Andokon keresztül", "Peru villamos energiájának több mint 40%-át adja", "Exportkapacitás a Pampa Melchorita LNG-üzemen át"],
      ro: ["Începerea operațiunilor în anul 2004", "Situat în bazinul Urubamba (regiunea Cusco)", "Descoperit de Shell între 1982 și 1983", "Transport prin gazoducte peste Munții Anzi", "Asigură peste 40% din energia electrică a țării", "Capacitate de export prin unitatea LNG Pampa Melchorita"],
