      hu: ["A modernizáció 2023-ban fejeződött be", "Napi 95 000 hordó feldolgozási kapacitás", "Több mint 5 milliárd dolláros beruházási költség", "A Petroperú állami vállalat üzemelteti", "Alacsony kéntartalmú üzemanyagok gyártása", "Peru legrégebbi olajipari központja az északi parton"],
