    name: { de: "Kupferhütte von Ilo", hu: "Ilo rézkohó", ro: "Topitoria de cupru Ilo", en: "Ilo Copper Smelter"},
    image: "/poi-images/ind-ilosmelter-economic-v2.webp",
    description: {
      de: "Verarbeitet Kupfererze aus nahegelegenen Minen und umfasst eine Raffinerie sowie eine Schwefelsäureanlage.",
      hu: "Feldolgozza a közeli bányákból származó rézércet, és tartalmaz egy finomítót, valamint egy kénsavgyárat.",
      ro: "Procesează minereul de cupru din minele din apropiere și include o rafinărie și o fabrică de acid sulfuric.",
      en: "Processes copper ore from nearby mines and includes a refinery and a sulfuric acid plant.",
      es: "Procesa minerales de cobre de las minas cercanas e incluye una refinería y una planta de ácido sulfúrico.",
      pt: "Processa minérios de cobre de minas próximas e inclui uma refinaria e uma planta de ácido sulfúrico.",
      fr: "Traite les minerais de cuivre provenant des mines voisines et comprend une raffinerie ainsi qu'une usine d'acide sulfurique.",
    },
    descriptionAdvanced: {
      de: "Die Kupferhütte von Ilo befindet sich in der Region Moquegua im Süden Perus und ist ein zentraler Bestandteil der industriellen Infrastruktur des Landes. Die Anlage wird von der Southern Copper Corporation betrieben und wurde bereits 1960 in Betrieb genommen, um Konzentrate aus den nahegelegenen Minen Toquepala und Cuajone zu verarbeiten. Im Jahr 2007 schloss das Unternehmen ein umfassendes Modernisierungsprojekt ab, bei dem die ISASMELT-Technologie eingeführt wurde, um die Effizienz zu steigern und die Schwefeldioxidemissionen drastisch zu reduzieren. In der Hütte wird das Kupferkonzentrat zu Anodenkupfer mit einem Reinheitsgrad von etwa 99,7 % geschmolzen, das anschließend in der benachbarten Raffinerie weiterverarbeitet oder über den Hafen von Ilo exportiert wird. Die strategische Lage an der Pazifikküste ermöglicht den direkten Zugang zu internationalen Märkten, insbesondere in Asien und Nordamerika. Heute gilt die Anlage als eine der modernsten ihrer Art in Lateinamerika und spielt eine entscheidende Rolle für das Wirtschaftswachstum der Region.",
      hu: "Az Ilo rézkohó Peru déli részén, Moquegua régióban található, és az ország ásványkincs-feldolgozó iparának egyik legfontosabb létesítménye. A Southern Copper Corporation által üzemeltetett egységet 1960-ban alapították, hogy feldolgozza a Toquepala és Cuajone bányákból származó rézkoncentrátumot. 2007-ben egy jelentős modernizációs program zárult le, amelynek keretében bevezették az ISASMELT technológiát, jelentősen csökkentve a kén-dioxid-kibocsátást és javítva a környezetvédelmi mutatókat. A kohóban a koncentrátumot rézanódokká alakítják, amelyek tisztasága eléri a 99,7%-ot, majd ezeket a közeli finomítóba szállítják tovább. Az üzem stratégiai elhelyezkedése Ilo kikötőjének közelében lehetővé teszi a finomított réz hatékony exportálását a globális piacokra. A létesítmény nemcsak Peru gazdasági stabilitásához járul hozzá, hanem kulcsszerepet játszik a helyi infrastruktúra fejlesztésében és a foglalkoztatásban is.",
      ro: "Topitoria de cupru de la Ilo este situată în regiunea Moquegua din sudul statului Peru și reprezintă o componentă vitală a infrastructurii de procesare a mineralelor din țară. Operată de Southern Copper Corporation, unitatea a fost inaugurată în 1960 pentru a procesa concentratele provenite de la minele Toquepala și Cuajone. În anul 2007, a fost finalizat un proiect major de modernizare care a inclus instalarea tehnologiei ISASMELT, reducând drastic emisiile de dioxid de sulf și îmbunătățind standardele de mediu. Topitoria transformă concentratul de cupru în anozi de cupru cu o puritate de aproximativ 99,7%, care sunt ulterior rafinați sau exportați prin portul Ilo. Poziția sa strategică pe coasta Pacificului facilitează accesul rapid la piețele internaționale, în special cele din Asia și America de Nord. În prezent, este una dintre cele mai mari și mai moderne facilități de acest tip din America Latină, fiind esențială pentru veniturile din export ale Perului.",
      en: "The Ilo Copper Smelter, located in the Moquegua region of southern Peru, is a critical component of the country's mineral processing infrastructure. Operated by the Southern Copper Corporation, the facility was established in 1960 and has since undergone several major modernization projects to improve its efficiency and environmental performance. The smelter processes copper concentrates from the Toquepala and Cuajone mines, converting them into copper anodes with a high level of purity. In 2007, a significant upgrade was completed, involving the installation of ISASMELT technology, which drastically reduced sulfur dioxide emissions. The smelter's strategic location near the Port of Ilo facilitates the export of refined copper to global markets, making it a cornerstone of Peru's export-driven economy. Today, it remains one of the largest facilities of its kind in the world, balancing industrial output with increasingly stringent environmental regulations.",
      es: "La Fundición de cobre de Ilo es un elemento notable de la geografía y la cultura peruana. Procesa minerales de cobre de las minas cercanas e incluye una refinería y una planta de ácido sulfúrico. Procesa minerales de cobre. Tiene una planta de ácido sulfúrico. Este sitio desempeña un papel en la economía peruana, desde la minería del cobre hasta la agricultura de la quinua y la pesca en el Pacífico. Como muchos lugares significativos en Perú, este sitio combina peculiaridades regionales entre el Pacífico, los Andes y la Amazonía con una importancia global. De este modo, el lugar contribuye al perfil polifacético de Perú, desde el legado inca y Machu Picchu hasta Lima y la cuenca del Amazonas.",
      pt: "A Fundição de cobre de Ilo é um elemento notável da geografia e cultura peruana. Processa minérios de cobre de minas próximas e inclui uma refinaria e uma planta de ácido sulfúrico. Processa minérios de cobre. Possui uma planta de ácido sulfúrico. Este local desempenha um papel na economia peruana, desde a mineração de cobre até a agricultura de quinoa e a pesca no Pacífico. Como muitos lugares significativos no Peru, este local combina peculiaridades regionais entre o Pacífico, os Andes e a Amazônia com uma importância global. Assim, o lugar contribui para o perfil multifacetado do Peru, desde a herança inca e Machu Picchu até Lima e a Bacia Amazônica.",
      fr: "La fonderie de cuivre d'Ilo est un élément remarquable de la géographie et de la culture péruviennes. Traite les minerais de cuivre provenant des mines voisines et comprend une raffinerie ainsi qu'une usine d'acide sulfurique. Traite les minerais de cuivre. Possède une usine d'acide sulfurique. Ce site joue un rôle dans l'économie péruvienne, de l'exploitation du cuivre à l'agriculture du quinoa, en passant par la pêche dans le Pacifique. Comme de nombreux lieux importants au Pérou, ce site combine des particularités régionales entre le Pacifique, les Andes et l'Amazonie avec une importance globale. Ainsi, ce lieu contribue au profil diversifié du Pérou, de l'héritage inca et du Machu Picchu à Lima et au bassin amazonien.",
    },
