      ro: ["Unitatea a început operațiunile în anul 1960", "Este deținută de Southern Copper Corporation", "Tehnologia ISASMELT a fost implementată în 2007", "Produce anozi de cupru cu o puritate de 99,7%", "Procesează minerale de la minele Toquepala și Cuajone", "Exportul se realizează prin portul maritim Ilo"],
