      fr: ["Traite les minerais de cuivre provenant des mines voisines et comprend une raffinerie ainsi qu'une usine d'acide sulfurique.", "Situé sur le territoire de la République du Pérou.", "Nichée entre la cordillère des Andes, le désert côtier et le bassin amazonien.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
