      hu: ["A finomító 1981-ben kezdte meg működését", "A Nexa Resources (Votorantim) tulajdonában van", "Éves kapacitása meghaladja a 340 000 tonnát", "Lima közelében, Lurigancho-Chosica negyedben található", "Elektrolízises eljárást alkalmaznak a fém kinyerésére", "Fontos kénsav- és kadmiumtermelő egység"],
      ro: ["Rafinăria a fost pusă în funcțiune în anul 1981", "Operată de Nexa Resources (Grupul Votorantim)", "Capacitate anuală de peste 340.000 de tone de zinc", "Localizată în districtul Lurigancho-Chosica, lângă Lima", "Utilizează procesul de extracție electrolitică", "Produce acid sulfuric și cadmiu ca subproduse"],
      en: ["The refinery started operations in 1981", "Owned and operated by Nexa Resources", "Annual production capacity exceeds 340,000 tons", "Located in the Lurigancho-Chosica district near Lima", "Employs an advanced electrolytic recovery process", "Produces sulfuric acid and cadmium as by-products"],
      es: ["Una de las refinerías de zinc más grandes del mundo, situada cerca de la capital, Lima.", "Ubicado en el territorio de la República del Perú.", "Situado entre la cordillera de los Andes, el desierto costero y la cuenca del Amazonas.", "Desempeña un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["Uma das maiores refinarias de zinco do mundo, localizada perto da capital, Lima.", "Localizado no território da República do Peru.", "Inserido entre a cordilheira dos Andes, o deserto costeiro e a Bacia Amazônica.", "Desempenha um papel na identidade local da região.", "Conhecido por sua importância paisagística ou cultural."],
      fr: ["L'une des plus grandes raffineries de zinc au monde, située près de la capitale, Lima.", "Situé sur le territoire de la République du Pérou.", "Nichée entre la cordillère des Andes, le désert côtier et le bassin amazonien.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
